import SwiftUI

struct DetailsView:View {
    @EnvironmentObject var app:AppViewModel;@StateObject private var model:DetailsViewModel
    init(item:MediaItem){_model=StateObject(wrappedValue:DetailsViewModel(item:item,streaming:StreamingService()))}
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){ZStack(alignment:.bottomLeading){CachedAsyncImage(url:URL(string:model.item.backdropURL),contentMode:.fill).frame(height:260).clipped().overlay(LinearGradient(colors:[.clear,.black],startPoint:.center,endPoint:.bottom));HStack(alignment:.bottom,spacing:16){CachedAsyncImage(url:URL(string:model.item.posterURL),contentMode:.fill).frame(width:115,height:170).clipped().clipShape(RoundedRectangle(cornerRadius:10));VStack(alignment:.leading){Text(model.item.title).font(.title.bold());Text([model.item.year,model.item.rating.isEmpty ? nil:"★ \(model.item.rating)"].compactMap{$0}.joined(separator:"  ")).foregroundStyle(.secondary)}}.padding()};if !model.item.originalTitle.isEmpty{Text(model.item.originalTitle).foregroundStyle(.secondary)};if !model.item.genres.isEmpty{Text(model.item.genres.joined(separator:" • ")).font(.subheadline).foregroundStyle(.secondary)};Text(model.item.overview);HStack{Button{Task{await model.prepare()}}label:{Label(model.item.mediaType=="tv" ? "Выбрать серию":"Смотреть",systemImage:"play.fill")}.buttonStyle(.borderedProminent).tint(.red);Button{app.library.toggle(model.item)}label:{Label(app.library.isFavorite(model.item) ? "В избранном":"В избранное",systemImage:app.library.isFavorite(model.item) ? "heart.fill":"heart")}.buttonStyle(.bordered)};sourcePicker;if model.loading{ProgressView().frame(maxWidth:.infinity)};if let error=model.error{ErrorPanel(message:error){Task{await model.prepare()}}}}.padding(.horizontal)}.background(Color.jiroxBackground).navigationBarTitleDisplayMode(.inline).task{await model.load()}}
    @ViewBuilder private var sourcePicker:some View{if !model.sources.isEmpty{Text("Источник").font(.headline);ScrollView(.horizontal){HStack{ForEach(model.sources){source in Button(source.name){Task{try? await model.select(source:source)}}.buttonStyle(.bordered)}}}};if !model.translations.isEmpty{Text("Озвучка").font(.headline);ScrollView(.horizontal){HStack{ForEach(model.translations){translation in Button(translation.name){model.select(translation:translation)}.buttonStyle(.bordered)}}}};if !model.seasons.isEmpty{Text("Сезоны").font(.headline);ScrollView(.horizontal){HStack{ForEach(model.seasons){season in Button(season.name){model.select(season:season)}.buttonStyle(.bordered)}}}};if !model.episodes.isEmpty{Text("Серии").font(.headline);LazyVStack{ForEach(model.episodes){episode in Button{Task{do{app.playback=try await model.play(episode:episode)}catch{model.error=error.localizedDescription}}}label:{HStack{CachedAsyncImage(url:URL(string:episode.imageURL),contentMode:.fill).frame(width:110,height:62).clipped();VStack(alignment:.leading){Text(episode.name);Text("Серия \(episode.number)").font(.caption).foregroundStyle(.secondary)};Spacer();Image(systemName:"play.circle.fill").font(.title).foregroundStyle(.red)}}.buttonStyle(.plain)}}}else if model.selectedTranslation != nil&&model.seasons.isEmpty{Button("Воспроизвести"){Task{do{app.playback=try await model.play()}catch{model.error=error.localizedDescription}}}.buttonStyle(.borderedProminent).tint(.red)}}
}
struct ErrorPanel:View{let message:String;let retry:()->Void;var body:some View{VStack{Text(message);Button("Повторить",action:retry)}.frame(maxWidth:.infinity).padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:12))}}
